import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3, 4]
    names = ["Alice", "Peter", "Arnold", "Eric"]
    mothers = ["Holly", "Kailyn", "Janelle", "Aniya"]
    flowers = ["carnations", "roses", "lilies", "daffodils"]

    solutions = []

    for name_perm in itertools.permutations(names):
        # Constraint 8: Alice is in the third house (index 2 in 0-based)
        if name_perm.index("Alice") != 2:
            continue

        pos_name = {n: name_perm.index(n) for n in names}

        for mother_perm in itertools.permutations(mothers):
            pos_mother = {m: mother_perm.index(m) for m in mothers}

            # Constraint 1: Alice's mother is Kailyn
            if mother_perm[pos_name["Alice"]] != "Kailyn":
                continue

            # Constraint 5: Arnold's mother is Holly
            if mother_perm[pos_name["Arnold"]] != "Holly":
                continue

            # Constraint 2: Mother Janelle is somewhere to the right of Arnold
            if pos_mother["Janelle"] <= pos_name["Arnold"]:
                continue

            for flower_perm in itertools.permutations(flowers):
                pos_flower = {f: flower_perm.index(f) for f in flowers}

                # Constraint 7: Lilies directly left of Alice
                if pos_flower["lilies"] + 1 != pos_name["Alice"]:
                    continue

                # Constraint 4: Eric loves daffodils
                if flower_perm[pos_name["Eric"]] != "daffodils":
                    continue

                # Constraint 6: Carnations to the right of Holly (i.e., Arnold's house)
                if pos_flower["carnations"] <= pos_name["Arnold"]:
                    continue

                # Constraint 3: Peter is to the right of carnations
                if pos_name["Peter"] <= pos_flower["carnations"]:
                    continue

                # All constraints satisfied; build solution
                solution_rows = []
                for i in range(4):
                    solution_rows.append([
                        str(i + 1),
                        name_perm[i],
                        mother_perm[i],
                        flower_perm[i]
                    ])

                solutions.append(solution_rows)

    # Prepare JSON output (take the first solution if multiple)
    if not solutions:
        raise RuntimeError("No solution found")

    result = {
        "solution": {
            "header": ["House", "Name", "Mother", "Flower"],
            "rows": solutions[0]
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
